interface RateClient {
  fetchRate(currency: "USD" | "GBP"): Promise<number>;
}

function createFakeClient(rates: Partial<Record<"USD" | "GBP", number>>): { client: RateClient; calls: string[] } {
  const calls: string[] = [];
  const client: RateClient = {
    async fetchRate(currency) {
      calls.push(currency);
      const rate = rates[currency];
      if (rate === undefined) throw new Error(`no rate for ${currency}`);
      return rate;
    },
  };
  return { client, calls };
}

const { client, calls } = createFakeClient({ USD: 1530 });
console.log(await client.fetchRate("USD"));
await client.fetchRate("GBP").catch((error: Error) => console.log(error.message));
console.log(calls);

