class CartError extends Error {}

function throwsA(run: () => unknown, ErrorClass: new (...args: any[]) => Error): string {
  try {
    run();
  } catch (error) {
    if (error instanceof ErrorClass) return "pass";
    return `fail: threw ${error instanceof Error ? error.name : String(error)}`;
  }
  return "fail: did not throw";
}

console.log(throwsA(() => { throw new CartError("empty"); }, CartError));
console.log(throwsA(() => (undefined as unknown as { x: number }).x, CartError));
console.log(throwsA(() => 42, CartError));

