function matchesSubset(actual: Record<string, unknown>, expected: Record<string, unknown>): string[] {
  const problems: string[] = [];
  for (const [key, want] of Object.entries(expected)) {
    if (actual[key] !== want) problems.push(`${key}: expected ${JSON.stringify(want)}, got ${JSON.stringify(actual[key])}`);
  }
  return problems;
}

