function toBeWholeKobo(received: unknown): { pass: boolean; message: string } {
  const pass = typeof received === "number" && Number.isSafeInteger(received) && received >= 0;
  return { pass, message: `expected ${String(received)} ${pass ? "not " : ""}to be a whole, non-negative number of kobo` };
}

