function groupBy<T, K extends PropertyKey>(items: readonly T[], keyOf: (item: T) => K): Partial<Record<K, T[]>> {
  const groups: Partial<Record<K, T[]>> = {};
  for (const item of items) {
    const key = keyOf(item);
    (groups[key] ??= []).push(item);
  }
  return groups;
}

const orders = [
  { id: "ord_1", status: "paid" as const },
  { id: "ord_2", status: "pending" as const },
  { id: "ord_3", status: "paid" as const },
];
const groups = groupBy(orders, (o) => o.status);
console.log(groups.paid?.map((o) => o.id), groups.pending?.map((o) => o.id));

